69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /**
75	     * Dedicated audit logger. A successful owner create emits a single line here carrying the new
76	     * owner's id, customer code, registration date and membership level, so the create side-effect
77	     * can be audited independently of the application log.
78	     */
79	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
80	
81	    private final ClinicService clinicService;
82	
83	    private final OwnerMapper ownerMapper;
84	
85	    private final PetMapper petMapper;
86	
87	    private final VisitMapper visitMapper;
88	
89	    /**
90	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
91	     * and a domain containing at least one dot, with no whitespace in any segment.
92	     */
93	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
94	
95	    /**
96	     * Email domains belonging to disposable/throwaway mail providers. An owner whose email address
97	     * is on this blocklist (compared case-insensitively on the domain, the part after the final
98	     * {@code '@'}) is rejected with a 400 Bad Request.
99	     */
100	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
101	        "mailinator.com",
102	        "tempmail.com",
103	        "guerrillamail.com");
104	
105	    /**
106	     * Required national-number length per E.164 country code. A normalized telephone whose country
107	     * code appears here must carry exactly this many national digits after the code; Australia
108	     * ({@code +61}) requires 9 and the North American Numbering Plan ({@code +1}) requires 10.
109	     * Country codes not listed are only subject to the generic 8-to-15 total-digit rule.
110	     */
111	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTH = Map.of("61", 9, "1", 10);
112	
113	    /**
114	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
115	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
116	     */
117	    private static final int MAX_OWNERS_PER_CITY = 50;
118	
119	    /**
120	     * Maximum number of owners that may be registered on a single day (by registration date). A create
121	     * attempted once this many owners already carry today's registration date is rejected with a
122	     * 429 Too Many Requests.
123	     */
124	    private static final int MAX_OWNERS_PER_DAY = 100;
125	
126	    /**
127	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
128	     * owners already carry the new owner's registration date, the created owner is flagged
129	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
130	     */
131	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
132	
133	    /**
134	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
135	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
136	     */
137	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
138	        "ST", "STREET",
139	        "RD", "ROAD",
140	        "AVE", "AVENUE");
141	
142	    /**
143	     * Inclusive 4-digit postcode range permitted per region, keyed by the region derived from the
144	     * owner's city ({@link Owner#getLocality()}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A
145	     * region not listed (the {@code 'UNKNOWN'} locality of a city with no known region) accepts any
146	     * 4-digit postcode.
147	     */
148	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
149	        "NSW", new int[] {2000, 2099},
150	        "VIC", new int[] {3000, 3099},
151	        "QLD", new int[] {4000, 4099});
152	
153	    public OwnerRestControllerV1(ClinicService clinicService,
154	                                 OwnerMapper ownerMapper,
155	                                 PetMapper petMapper,
156	                                 VisitMapper visitMapper) {
157	        this.clinicService = clinicService;
158	        this.ownerMapper = ownerMapper;
159	        this.petMapper = petMapper;
160	        this.visitMapper = visitMapper;
161	    }
162	
163	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
164	    @Override
165	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
166	        Collection<Owner> owners;
167	        if (lastName != null) {
168	            owners = this.clinicService.findOwnerByLastName(lastName);
169	        } else {
170	            owners = this.clinicService.findAllOwners();
171	        }
172	        if (owners.isEmpty()) {
173	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
174	        }
175	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
181	        Owner owner = this.clinicService.findOwnerById(ownerId);
182	        if (owner == null) {
183	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
184	        }
185	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
191	        validateRequiredFields(ownerFieldsDto);
192	        HttpHeaders headers = new HttpHeaders();
193	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
194	        rejectFutureRegistrationDate(owner.getRegistrationDate());
195	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
196	        owner.setRegistrationDate(registrationDate);
197	        requireDailyCapacity(registrationDate);
198	        requireCityHasCapacity(owner.getCity());
199	        validatePostcode(owner);
200	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
201	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
202	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
203	        owner.setHouseholdId(computeHouseholdId(owner.getLastName(), owner.getPostcode()));
204	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
205	        requireNoHouseholdDuplicate(owner, declaredHouseholdMember);
206	        requireUniqueIdentity(owner);
207	        flagPossibleDuplicate(owner, declaredHouseholdMember);
208	        owner.setCustomerCode(owner.buildCustomerCode());
209	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
210	        stampHouseholdSize(owner);
211	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
212	        this.clinicService.saveOwner(owner);
213	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
214	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
215	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
216	        headers.setLocation(UriComponentsBuilder.newInstance()
217	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
218	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
219	    }
220	
221	    /**
222	     * Rejects a create whose supplied registration date is later than the server's current date. A
223	     * registration may be back-dated but never post-dated, so a future date is treated as a client
224	     * error. A {@code null} supplied date (the client omitted it) is allowed, as it defaults to the
225	     * server date.
226	     *
227	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} when the
228	     *     client omitted it
229	     * @throws FutureRegistrationDateException if the supplied date is after the server's current date
230	     */
231	    private void rejectFutureRegistrationDate(LocalDate suppliedRegistrationDate) {
232	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
233	            throw new FutureRegistrationDateException(suppliedRegistrationDate);
234	        }
235	    }
236	
237	    /**
238	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
239	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
240	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
241	     * existed prior to this create.
242	     *
243	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
244	     *     a business day
245	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
246	     *     registered on that business day
247	     */
248	    private void requireDailyCapacity(LocalDate registrationDate) {
249	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
250	            throw new DailyOwnerLimitException(registrationDate);
251	        }
252	    }
253	
254	    /**
255	     * Counts the existing owners whose registration date equals the given business-day date. This is
256	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
257	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
258	     * the bulk-signup warning.
259	     *
260	     * @param registrationDate the effective business-day registration date to count against
261	     * @return the number of pre-existing owners registered on that date
262	     */
263	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
264	        return this.clinicService.findAllOwners().stream()
265	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
266	            .count();
267	    }
268	
269	    /**
270	     * Rejects an owner whose city already contains the maximum allowed number of owners
271	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
272	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
273	     * create.
274	     *
275	     * @param city the city of the owner being created
276	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
277	     */
278	    private void requireCityHasCapacity(String city) {
279	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
280	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
281	            .count();
282	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
283	            throw new CityOwnerLimitException(city);
284	        }
285	    }
286	
287	    /**
288	     * Validates a supplied postcode against the owner's region. Postcode is optional: an owner with no
289	     * postcode is accepted unchanged. When present it is a 4-digit string (enforced by the request
290	     * schema) that must fall within the inclusive range permitted for the region derived from the
291	     * owner's city ({@link #REGION_POSTCODE_RANGES}); a city whose region is unknown accepts any 4-digit
292	     * postcode. An out-of-range postcode is rejected with a 400 Bad Request.
293	     *
294	     * @param owner the owner being created, with its city and postcode set
295	     * @throws InvalidOwnerFieldsException if a supplied postcode is out of range for the city's region
296	     */
297	    private void validatePostcode(Owner owner) {
298	        String postcode = owner.getPostcode();
299	        if (postcode == null) {
300	            return;
301	        }
302	        int[] range = REGION_POSTCODE_RANGES.get(owner.getLocality());
303	        if (range == null) {
304	            return;
305	        }
306	        int value = Integer.parseInt(postcode);
307	        if (value < range[0] || value > range[1]) {
308	            throw new InvalidOwnerFieldsException(List.of("postcode"));
309	        }
310	    }
311	
312	    /**
313	     * Counts the existing owners that already share the given first name and last name, compared
314	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
315	     * owners that existed prior to this create.
316	     *
317	     * @param firstName the first name of the owner being created
318	     * @param lastName the last name of the owner being created
319	     * @return the number of pre-existing namesakes
320	     */
321	    private int countNamesakes(String firstName, String lastName) {
322	        return (int) this.clinicService.findAllOwners().stream()
323	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
324	                && equalsIgnoreCase(existing.getLastName(), lastName))
325	            .count();
326	    }
327	
328	    /**
329	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
330	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
331	     *
332	     * @param a the first value, possibly {@code null}
333	     * @param b the second value, possibly {@code null}
334	     * @return whether the values are equal ignoring case
335	     */
336	    private boolean equalsIgnoreCase(String a, String b) {
337	        return a == null ? b == null : a.equalsIgnoreCase(b);
338	    }
339	
340	    /**
341	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
342	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
343	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
344	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
345	     *
346	     * @param ownerFieldsDto the submitted owner fields
347	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
348	     */
349	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
350	        List<String> invalidFields = new ArrayList<>();
351	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
352	            invalidFields.add("firstName");
353	        }
354	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
355	            invalidFields.add("lastName");
356	        }
357	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
358	            invalidFields.add("address");
359	        }
360	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
361	            invalidFields.add("city");
362	        }
363	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
364	            invalidFields.add("telephone");
365	        }
366	        if (!invalidFields.isEmpty()) {
367	            throw new InvalidOwnerFieldsException(invalidFields);
368	        }
369	    }
370	
371	    /**
372	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
373	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
374	     * what gets stored and returned.
375	     *
376	     * @param telephone the raw telephone value from the request
377	     * @return the normalized E.164 telephone number
378	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
379	     */
380	    private String normalizeTelephone(String telephone) {
381	        String e164 = toE164(telephone);
382	        if (e164 == null) {
383	            throw new InvalidOwnerFieldsException(List.of("telephone"));
384	        }
385	        return e164;
386	    }
387	
388	    /**
389	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
390	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
391	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
392	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
393	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
394	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
395	     *
396	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
397	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
398	     *
399	     * @param telephone the raw telephone value, possibly {@code null}
400	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
401	     */
402	    private String toE164(String telephone) {
403	        if (telephone == null) {
404	            return null;
405	        }
406	        String cleaned = telephone.replaceAll("[ \\-()]", "");
407	        String digits;
408	        if (cleaned.startsWith("+")) {
409	            digits = cleaned.substring(1);
410	        } else {
411	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
412	            digits = "61" + national;
413	        }
414	        if (!digits.matches("[0-9]{8,15}")) {
415	            return null;
416	        }
417	        if (!nationalNumberLengthValid(digits)) {
418	            return null;
419	        }
420	        return "+" + digits;
421	    }
422	
423	    /**
424	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
425	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
426	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
427	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
428	     * accepted, leaving only the generic total-length rule to apply.
429	     *
430	     * @param digits the E.164 digits without the leading {@code '+'}
431	     * @return {@code true} if the national-number length matches the country code's requirement
432	     */
433	    private boolean nationalNumberLengthValid(String digits) {
434	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
435	            String code = entry.getKey();
436	            if (digits.startsWith(code)) {
437	                return digits.length() - code.length() == entry.getValue();
438	            }
439	        }
440	        return true;
441	    }
442	
443	    /**
444	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
445	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
446	     * and returned lower-cased.
447	     *
448	     * @param email the raw email value from the request, possibly {@code null}
449	     * @return the lower-cased email, or {@code null} when none was supplied
450	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
451	     */
452	    private String normalizeEmail(String email) {
453	        if (!StringUtils.hasText(email)) {
454	            return null;
455	        }
456	        String trimmed = email.trim();
457	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
458	            throw new InvalidOwnerFieldsException(List.of("email"));
459	        }
460	        String normalized = trimmed.toLowerCase(Locale.ROOT);
461	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
462	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
463	            throw new InvalidOwnerFieldsException(List.of("email"));
464	        }
465	        return normalized;
466	    }
467	
468	    /**
469	     * Rejects an owner whose whole identity key is already used by an existing owner. This is the
470	     * single consolidated duplicate check: the identity key ({@link Owner#getIdentityKey()}) is the
471	     * owner's normalized telephone, email (empty when absent) and household id joined with
472	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
473	     * owner's. Because the telephone is part of the key, two members of the same household
474	     * (same {@code householdId}) with different telephones have different identity keys and are both
475	     * allowed.
476	     *
477	     * @param owner the owner being created, with its normalized telephone, email and household id set
478	     * @throws DuplicateIdentityException if another owner already has this identity key
479	     */
480	    private void requireUniqueIdentity(Owner owner) {
481	        String identityKey = owner.getIdentityKey();
482	        boolean inUse = this.clinicService.findAllOwners().stream()
483	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
484	        if (inUse) {
485	            throw new DuplicateIdentityException(identityKey);
486	        }
487	    }
488	
489	    /**
490	     * Flags the owner being created as a possible (soft) duplicate of an existing owner. A soft match is
491	     * not a hard duplicate (its identity key is unique, already enforced by {@link #requireUniqueIdentity})
492	     * but it shares an existing owner's last name (compared case-insensitively) and postcode (both
493	     * present and equal) while carrying a different normalized telephone. When such an existing owner is
494	     * found the created owner is flagged ({@code possibleDuplicate} true) with {@code possibleDuplicateOf}
495	     * set to that owner's id; the lowest matching id is used when several owners match. Otherwise the flag
496	     * is false and {@code possibleDuplicateOf} is left unset.
497	     *
498	     * <p>A declared household member (one created with {@code sharesHousehold}) is never a suspected
499	     * duplicate: it has deliberately opted in to sharing its household, so the flag is forced false.
500	     *
501	     * @param owner the owner being created, with its normalized telephone and postcode set
502	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
503	     */
504	    private void flagPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
505	        if (declaredHouseholdMember || owner.getPostcode() == null) {
506	            owner.setPossibleDuplicate(false);
507	            return;
508	        }
509	        Integer matchId = this.clinicService.findAllOwners().stream()
510	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
511	                && owner.getPostcode().equals(existing.getPostcode())
512	                && !owner.getTelephone().equals(existing.getTelephone()))
513	            .map(Owner::getId)
514	            .min(Integer::compareTo)
515	            .orElse(null);
516	        owner.setPossibleDuplicate(matchId != null);
517	        owner.setPossibleDuplicateOf(matchId);
518	    }
519	
520	    /**
521	     * Rejects a create that would join an existing household unless it has opted in via
522	     * {@code sharesHousehold}. The household is keyed on the deterministic {@code householdId} (derived
523	     * from the normalized last name and postcode; see {@link #computeHouseholdId}), so any existing
524	     * owner carrying the same {@code householdId} is a member of the same household. When one exists and
525	     * the create has not declared household membership, the second owner is a household duplicate.
526	     *
527	     * <p>A create that declares {@code sharesHousehold} bypasses this block entirely and is created as a
528	     * declared household member.
529	     *
530	     * @param owner the owner being created, with its deterministic {@code householdId} already set
531	     * @param declaredHouseholdMember whether the owner opted in to its household via {@code sharesHousehold}
532	     * @throws DuplicateHouseholdException if an existing owner already shares the household and the
533	     *     create did not declare {@code sharesHousehold}
534	     */
535	    private void requireNoHouseholdDuplicate(Owner owner, boolean declaredHouseholdMember) {
536	        if (declaredHouseholdMember) {
537	            return;
538	        }
539	        String householdId = owner.getHouseholdId();
540	        boolean inUse = this.clinicService.findAllOwners().stream()
541	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
542	        if (inUse) {
543	            throw new DuplicateHouseholdException(householdId);
544	        }
545	    }
546	
547	    /**
548	     * Stamps the household's member count after this create ({@code householdSize}) onto every member of
549	     * the household - the existing owners that share the deterministic {@code householdId} and the new
550	     * one - so the shared size can be read back from any of them. The count is the number of existing
551	     * members plus the owner being created.
552	     *
553	     * @param owner the owner being created, with its deterministic {@code householdId} already set
554	     */
555	    private void stampHouseholdSize(Owner owner) {
556	        String householdId = owner.getHouseholdId();
557	        List<Owner> members = this.clinicService.findAllOwners().stream()
558	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
559	            .toList();
560	        int householdSize = members.size() + 1;
561	        owner.setHouseholdSize(householdSize);
562	        for (Owner member : members) {
563	            member.setHouseholdSize(householdSize);
564	            this.clinicService.saveOwner(member);
565	        }
566	    }
567	
568	    /**
569	     * Computes the deterministic, shared household identifier for a last name and postcode: the first
570	     * 12 upper-case hexadecimal characters (the first 6 bytes) of the SHA-256 digest of
571	     * {@code normalizedLastName + '|' + postcode}. The last name is normalized (case-insensitive,
572	     * whitespace-collapsed) and an absent postcode contributes an empty string, so every owner that
573	     * shares a last name and postcode computes the same identifier and therefore the same household.
574	     *
575	     * @param lastName the last name of the household
576	     * @param postcode the postcode of the household, possibly {@code null}
577	     * @return the 12-character upper-case hex household identifier
578	     */
579	    private String computeHouseholdId(String lastName, String postcode) {
580	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
581	        try {
582	            byte[] digest = MessageDigest.getInstance("SHA-256")
583	                .digest(key.getBytes(StandardCharsets.UTF_8));
584	            StringBuilder hex = new StringBuilder(12);
585	            for (int i = 0; i < 6; i++) {
586	                hex.append(String.format("%02X", digest[i]));
587	            }
588	            return hex.toString();
589	        } catch (NoSuchAlgorithmException e) {
590	            throw new IllegalStateException("SHA-256 algorithm not available", e);
591	        }
592	    }
593	
594	    /**
595	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
596	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
597	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
598	     *
599	     * @param value the raw value, possibly {@code null}
600	     * @return the normalized value
601	     */
602	    private String normalizeForHousehold(String value) {
603	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
604	    }
605	
606	    /**
607	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
608	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
609	     * value yields an empty string.
610	     *
611	     * @param value the raw value, possibly {@code null}
612	     * @return the trimmed, whitespace-collapsed value
613	     */
614	    private String collapseWhitespace(String value) {
615	        if (value == null) {
616	            return "";
617	        }
618	        return value.trim().replaceAll("\\s+", " ");
619	    }
620	
621	    /**
622	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
623	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
624	     * is upper-cased, and common street-type abbreviations are expanded as whole words
625	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
626	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
627	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
628	     *
629	     * @param address the raw address value, possibly {@code null}
630	     * @return the normalized address
631	     */
632	    private String normalizeAddress(String address) {
633	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
634	        if (collapsed.isEmpty()) {
635	            return "";
636	        }
637	        String[] tokens = collapsed.split(" ");
638	        StringBuilder normalized = new StringBuilder();
639	        for (int i = 0; i < tokens.length; i++) {
640	            if (i > 0) {
641	                normalized.append(' ');
642	            }
643	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
644	        }
645	        return normalized.toString();
646	    }
647	
648	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
649	    @Override
650	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
651	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
652	        if (currentOwner == null) {
653	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
654	        }
655	        currentOwner.setAddress(ownerFieldsDto.getAddress());
656	        currentOwner.setCity(ownerFieldsDto.getCity());
657	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
658	        currentOwner.setLastName(ownerFieldsDto.getLastName());
659	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
660	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
661	        this.clinicService.saveOwner(currentOwner);
662	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
663	    }
664	
665	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
666	    @Transactional
667	    @Override
668	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
669	        Owner owner = this.clinicService.findOwnerById(ownerId);
670	        if (owner == null) {
671	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
672	        }
673	        this.clinicService.deleteOwner(owner);
674	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
675	    }
676	
677	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
678	    @Override
679	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
680	        Owner owner = this.clinicService.findOwnerById(ownerId);
681	        if (owner == null) {
682	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
683	        }
684	        HttpHeaders headers = new HttpHeaders();
685	        Pet pet = petMapper.toPet(petFieldsDto);
686	        owner.setId(ownerId);
687	        pet.setOwner(owner);
688	        pet.getType().setName(null);
689	        this.clinicService.savePet(pet);
690	        PetDto petDto = petMapper.toPetDto(pet);
691	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
692	            .buildAndExpand(pet.getId()).toUri());
693	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
694	    }
695	
696	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
697	    @Override
698	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
699	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
700	        if (currentOwner != null) {
701	            Pet currentPet = this.clinicService.findPetById(petId);
702	            if (currentPet != null) {
703	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
704	                currentPet.setName(petFieldsDto.getName());
705	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
706	                this.clinicService.savePet(currentPet);
707	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
708	            }
709	        }
710	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
711	    }
712	
713	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
714	    @Override
715	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
716	        HttpHeaders headers = new HttpHeaders();
717	        Visit visit = visitMapper.toVisit(visitFieldsDto);
718	        Pet pet = new Pet();
719	        pet.setId(petId);
720	        visit.setPet(pet);
721	        this.clinicService.saveVisit(visit);
722	        VisitDto visitDto = visitMapper.toVisitDto(visit);
723	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
724	            .buildAndExpand(visit.getId()).toUri());
725	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
726	    }
727	
728	
729	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
730	    @Override
731	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
732	        Owner owner = this.clinicService.findOwnerById(ownerId);
733	        if (owner != null) {
734	            Pet pet = owner.getPet(petId);
735	            if (pet != null) {
736	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
737	            }
738	        }
739	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
740	    }
741	}
